import{_ as l,l as o,o as e,c as s,v as L,p as R,x as r,d as i,i as n,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"SLR 与 LALR","description":"","frontmatter":{"title":"SLR 与 LALR","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/slr-lalr.md","filePath":"cs/slr-lalr.md","lastUpdated":1789023840000}'),A={name:"cs/slr-lalr.md"};function c(h,a,p,m,S,_){const t=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=L('<h1 id="slr-与-lalr" tabindex="-1">SLR 与 LALR <a class="header-anchor" href="#slr-与-lalr" aria-label="Permalink to &quot;SLR 与 LALR&quot;">​</a></h1><div class="epigraph"><p>同一张项集规范族上，SLR 用 FOLLOW 决定归约，LALR 把 LR(1) 项按芯合并；表更小，认的语言夹在 SLR 与 LR(1) 之间。</p><footer>—— 据 DeRemer, Simple LR(k) Grammars, 1971；DeRemer and Pennello, Efficient Computation of LALR(1) Look-Ahead Sets, 1982；龙书第 4 章整理</footer></div><p>上一课<a href="/cs/lr-shift-reduce">LR 与移进归约</a>给出项、闭包、GOTO、移进/归约冲突，并声明 SLR 用 FOLLOW、LALR 是 Yacc 的实用点，没有填表。本课不重画最右推导。缺口是三种表的差别：SLR(1)、LALR(1)、LR(1)——状态怎么增，冲突怎么少。归约时可挂语义动作，下一课 AST 就在这里接。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LR(0) 项不带前瞻，同一状态里两条完成项就会归约/归约冲突。SLR：完成项 \\(A\\to\\alpha\\cdot\\) 只对 \\(a\\in\\mathrm{FOLLOW}(A)\\) 归约。FOLLOW 是粗前瞻，可能仍冲突。LR(1) 项 \\([A\\to\\alpha\\cdot\\beta,a]\\) 把前瞻钉在项上，状态变多，冲突最少（在确定 CFG 的实用范围内）。LALR：把芯（忽略前瞻的 LR(0) 部分）相同的 LR(1) 状态合并，前瞻取并。状态数约等于 LR(0) 族，前瞻比 SLR 细。</p><p>缺口是这层包含：\\(\\mathrm{SLR}\\subset\\mathrm{LALR}\\subset\\mathrm{LR}(1)\\)（能无冲突分析的文法类）。Yacc/bison 默认 LALR(1)。if-else 仍常要 <code>%left</code>/<code>%nonassoc</code> 人工消二义，LALR 本身并不消去二义。</p><h3 id="合并可能引入新冲突" tabindex="-1">合并可能引入新冲突 <a class="header-anchor" href="#合并可能引入新冲突" aria-label="Permalink to &quot;合并可能引入新冲突&quot;">​</a></h3><p>两个 LR(1) 状态芯同、前瞻不同，合并后可能在同一完成项上多出一个不该归约的符号。故存在 LALR 冲突而规范 LR(1) 无冲突的文法。本课承认，不构造病态长例。</p><p><span class="marginnote">DeRemer 的 SLR 与 LALR。龙书 4.6–4.7 节比较表大小。Knuth LR(\\(k\\)) 是上一课总框架。本课要生成器选哪张表，不手填 GOTO 全表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从增广文法建 LR(0) 项集（SLR/LALR 的芯）。SLR：归约栏填 FOLLOW。要 LALR：传播前瞻（DeRemer–Pennello）或先 LR(1) 再合并。冲突仍在则改文法或加优先级。</p>',11)),(e(),R(d,null,{default:r(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IT%5B%22%E9%A1%B9%E9%9B%86%E6%97%8F%22%5D%20--%3E%20SLR%5B%22SLR%EF%BC%9AFOLLOW%20%E5%BD%92%E7%BA%A6%22%5D%0A%20%20IT%20--%3E%20LALR%5B%22LALR%EF%BC%9A%E5%90%88%E5%B9%B6%E8%8A%AF%20%2B%20%E5%B9%B6%E5%89%8D%E7%9E%BB%22%5D%0A%20%20IT%20--%3E%20LR1%5B%22LR(1)%EF%BC%9A%E9%A1%B9%E8%87%AA%E5%B8%A6%20a%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=L('<p>分析循环与上一课相同：查动作表直到接受。归约 \\(A\\to\\alpha\\) 时执行用户动作：<code>new</code> AST 节点——对象下一课才定义，本课只留挂钩。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>左递归对三族都友好。表的体积：LR(1) 可能上千态，LALR 几百，够一门课的语言。错误恢复（恐慌模式丢记号）是生成器附加，本课点名。</p><p>不要把 FOLLOW 当 FIRST：FOLLOW 管「A 推完后后面能见什么」，归约用它。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列出闭包伪代码全文，不处理 GLR。后课默认：实用语法用 LALR/SLR 表驱动；归约动作构造抽象语法树，丢掉分层非终结符。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SLR 用 FOLLOW；LR(1) 项带前瞻；LALR 合并芯。</li><li>文法类 SLR ⊂ LALR ⊂ LR(1)；Yacc 用 LALR。</li><li>归约挂钩给下一课 AST。</li><li>出处：DeRemer, 1971；DeRemer and Pennello, 1982；龙书第 4 章。</li></ul>',8))])}const E=l(A,[["render",c]]);export{f as __pageData,E as default};
